    def generate_cnf(n):
        cnf = []
        for _ in range(n * (n - 1) // 2):
            literals = [random.randint(1, n), random.randint(-n, -1)]
            random.shuffle(literals)
            cnf.append(tuple(literals))
        return cnf

    def resolution_width(cnf):
        clauses = set(cnf)
        unit_clauses = {c for c in clauses if len(c) == 1}

        while unit_clauses:
            new_unit_clause = None
            for c in unit_clauses:
                if c in clauses:
                    clauses.remove(c)
                    new_unit_clause = (-c[0],)
                    break

            if not new_unit_clause:
                return -1

            unit_clauses.discard(new_unit_clause)
            for c in clauses:
                if new_unit_clause[0] in c and -new_unit_clause[0] in c:
                    return -1
                if new_unit_clause[0] in c:
                    clauses.remove(c)
                    new_c = tuple(l for l in c if l != new_unit_clause[0])
                    if len(new_c) == 1:
                        unit_clauses.add(new_c)

        return max(len(c) for c in clauses) if clauses else 0

